(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["se"] = {"ui":{"skip":"Njuike sisdollui","back":"← Máhcca AI-gilii","lang.button":"Giella: {name}","lang.dialog":"Vállje giela","lang.search":"Oza gielaid","lang.none":"Ii oktage giella heive","lang.notYet":"{name} ii leat vel jorgaluvvon","theme.aria":"Rievdat fáddá: čuvges, čáhppes dahje ollesčáhppes","theme.toLight":"Rievdat čuvges fáddái","theme.toDark":"Rievdat čáhppes fáddái","theme.toBlack":"Rievdat ollesčáhppes fáddái (duohta čáhppat, buorre OLED-skearruide)","words.underline":"Vuollesárggo dáid sániid siiddus","words.underlineHelp":"Bija sáhpána čuoggáid vuollesárgojuvvon sáni badjelii dahje deaddil dan, de oainnát maid dat mearkkaša.","index.title":"AI-gile: du AI-ovdánahttinjoavku, oktan tavllas","index.description":"AI-gile lea kanban-tavla AI-prográmmenjoavkkuide. Sii barget go don oađát; dutnje báhcá okta oanehis čoalku maid galggat mearridit, geahččalit ja dohkkehit.","hero.logoAlt":"AI-gile-tavlla ikovdná","hero.h1.html":"Du AI-ovdánahttinjoavku, oktan&nbsp;tavllas.","hero.alpha":"🐣 Gidda pre-alfa","hero.alphaTitle":"Ođđa ja ii vel gárvvis: giitu go geahččalat!","hero.lede":"Sii hukset go don oađát. Don čuoččáhat ja oainnát oanehis čoalkku: moadde gažaldaga, moadde juoga maid geahččalit, ovtta guovtte fiolleta diamántta. Deaddil, dohkke ja ruoktot gáfii.","dl.windows":"Windows-app","dl.browser":"Jođit dan neahttabláđđejeaddjis","dl.messenger":"📱 Messenger du telefovdnii","dl.soon":"Boahtá dál","dl.notify":"🔔 Muital go rahpasa","dl.notifySmall":"Alfa dahje beta","hero.secondary":"Agile, muhto joavku ii dárbbaš stand-up-gáfe. (Sii dahket stand-upaid siva.)","pitch.h2":"AI-gile nu máŋga sániin go háliidat","pitch.lede":"Vállje guhkkodaga, ovtta sánis 144 sátnái. Juohke guhkkodat lea iežas čilgehus, čállojuvvon dan stuorrodahkii. Geassa sliderii dahje geavat nuolaboalu.","pitch.rangeLabel":"Guhkkodat sániin","pitch.dice":"🎲 eará veršuvdna","pitch.words.one":"{n} sátni","pitch.words.other":"{n} sáni","pitch.letters.one":"{n} bustávva","pitch.letters.other":"{n} bustávva","pitch.chars.one":"{n} mearka","pitch.chars.other":"{n} mearkka","count.line.html.one":"{n} kortta tavllas dál","count.line.html.other":"{n} korttá tavllas dál","people.humans.html.one":"👥 {n} olmmoš","people.humans.html.other":"👥 {n} olbmo","people.agents.html.one":"🤖 {n} agenta","people.agents.html.other":"🤖 {n} agentta","people.working.html.one":"⚡ {n} barggus dál","people.working.html.other":"⚡ {n} barggus dál","pre.title":"AI-gile: juoga huksejuvvo","pre.description":"Dáppe huksejuvvo juoga: tavval gos AI-joavkkut huksejit dan maid don bivddát, ja oahpahit du seammás. Dál gidda pre-alfa ustibiiguin.","pre.h1":"Dáppe huksejuvvo juoga. 🤫","pre.line":"Tavval gos AI-joavkkut huksejit dan maid don bivddát, ja oahpahit du seammás. Dál gidda pre-alfa ustibiiguin.","pre.btn":"🔔 Muital go rahpasa","pre.peek":"Láse duogábealde: duohta tavval, njuolga. Juohke kortta lea ivdnás sárgá.","pre.peekFake":"Láse duogábealde: nu orru bargi tavval.","features.aria":"Maid dat dahká","f.pile.h":"Okta čoalku dutnje","f.pile.html":"<b>Dutnje</b> čohkke buot mii vuordá du, buot prošeavttain: gažaldagaid, dan maid galgá geahččalit, bargguid maid dušše olmmoš sáhttá dahkat. Du ráidu muitala mii boahtá ovdal ja man guhká dat bivdá.","f.sleep.h":"Joavkkut mat barget go don oađát","f.sleep.p":"Juohke prošeavttas lea jođiheaddji ja AI-agenttaid joavku. Čále kommeantta kortii, joavku čuoččáha, bargá barggu ja addá dan ruovttoluotta lávkkiiguin maid váiban olmmoš maid čuovvola.","f.tester.h":"AI-geahččaleaddji dárkkista ovddemusat","f.tester.p":"Ovdal go maidege joavdá dutnje, geahččaleaddji čuovvu lávkkiid appa kopiias ja čájeha maid oaidnigođii, ruvttagova bokte. Bláđđe čađa daid mat leat mannan čađa ja dohkke oktii deaddilemiin.","f.proof.h":"Duođaštus, ii loahpahusat","f.proof.p":"Juohke addin čájeha mii lea rievdan: fiillat, erohus, ruvttagovat. Ii dárbbaš rahpat juohke appa vai oainnát lea go gárvvis.","f.chat.h":"Hupmá jođiheaddjiidat","f.chat.p":"Discord-lágan bálká: okta ikovdná juohke prošektii, fiolleta diamántta dan várás mii dárbbaša du. Sádde jođiheaddjái jurdaga; son dahká das kortaid ja plána, ✅ Go-boalloin.","f.tidy.h":"Doallá iežas heivvolažžan","f.tidy.p":"Seammalágan kortta čohkkejuvvojit oktan, seaguhuvvan namat divvojuvvojit, ja token-dárkkisteapmi doallá koda geahpesin. Unnit molsut gaskkas, unnit jurddašit.","f.private.h":"Du, du dihtoris","f.private.li1":"Tavla johtá du iežas mášiinnas ja vástida dušše dutnje.","f.private.li2":"Olbmuid gaskasaš priváhta čállosat leat gaskkohagas čihkkojuvvon.","f.private.li3":"Eai kontut, eai čuovvuleaddjit, eai cookie:t.","f.lang.h":"Du iežat gillii","f.lang.p":"Badjel 120 gielas, hollánddas, kymras ja japánas mearrarievvárgillii, Yoda- ja klingon-gillii, ja jođánit molsun eaŋgalasgillii fágasániid várás.","f.service.h":"Jurdagis duohta bálvalussan","f.service.p":"Leatgo huksen juoga AI:in maid olbmot dál geavahit? Merke dan bálvalussan, de távval veahkeha du jođihit dan bures: doaibmaáigedárkkisteamit, almmolaš dilálašsiidu, dáhpáhusat čállosiin, rievdadusat mat dárbbašit Go, sihkkarastimat dárkkistuvvon juohke beaivvi. Veahkki oahpaha juohke lávkki dađistaga.","msgr.h2":"AI-gile Messenger: du joavku du lummas","msgr.p1":"Hupmal du AI-joavkkuin rahpakeahttá tavlla. Čátte du prošeaktajođiheddjiiguin ja ustibiiguin, ja geahča gortta testenlávkkiid ja vástit daidda, buot du telefovnnas.","msgr.p2":"Čatnan dihte dan, skánne QR-koda du tavllas. Vuosttaš geardde? Ustitlaš demočátta čájeha dutnje mo buot doaibmá.","msgr.when":"Vuos Android, dasto neahttaveršuvdna telefovnnaide ja iPhone:i.","msgr.who":"Du prošeaktajođiheaddji","msgr.b1":"Seavdnjes moduse divvun lea gárvvis. Háliidatgo testenlávkkiid?","msgr.b2":"Juo, giitu!","msgr.b3":"1. Raba Heivehusaid. 2. Vállje Seavdnjes. Orrugo riekta?","tl.aria":"Áigeráidu vuosttaš sártnus ovdánanplánii","tl.h2":"Vuosttaš sártnus dasa mii boahtá","tl.lede":"Duohta beaivemearit ja áiggit, du iežat áigeavádagas. Otne maŋŋá lea plána, ii loahpaheames beaivemeriid.","tl.today":"Otne","tl.planned":"plánejuvvon","tl.doing":"barggus","tl.cards.one":"{n} kortta","tl.cards.other":"{n} korttá","join.h2":"Searvva","join.lede":"AI-gile huksejit okta skeaggat ártet olmmoš geas lea AuDHD ja muhtin soađit psyhkalaš dearvvašvuođain, ja ollu gierdavaš agenttat. Dál lea priváhta, giddes alfas ustibiiguin. Háliidat go geahččalit go rahpasa?","join.btn":"Registreara beroštumi","join.small":"Mii čálit e-poastta, eai eará","footer.tag":"AI-gile. Eai čuovvuleaddjit, eai cookie:t, ii stand-up-gáffe.","footer.licence":"Fitnodatlisensa","footer.status":"Dilli","footer.privacy":"Maid mii vurket","footer.thanks":"Riŋgemat: giitu ChilledChat:ii","form.sending":"Sádde…","form.failed":"Dat ii lihkostuvvan: geahččal maŋŋeláguin fas.","form.offline":"Ii olahan AI-gilii: geahččal maŋŋeláguin fas.","form.keep":"Mii geavahit dán dušše vástidit dutnje, ja de sihkkut dan. Eai čuovvuleaddjit, eai cookie:t.","form.keepLink":"Maid mii vurket","interest.title":"AI-gile: muital go alfa rahpasa","interest.description":"Guođe e-poastta vai gullat go AI-gilen gidda alfa dahje beta rahpasa.","interest.h1":"🔔 Muital go rahpasa","interest.lede":"AI-gile lea gidda pre-alfas. Guođe e-poastta ja mii čálit oktii, go lea sadji dutnje.","interest.email":"Du e-poastta","interest.which":"Mii geahččaleapmi?","interest.alpha":"Gidda alfa: árra, garra, ollu rievdadusat","interest.beta":"Beta: sihkkarat, maŋŋelis","interest.both":"Goabbat, goappá ovdal boahtá","interest.submit":"Bija mu listui","interest.thanks":"Giitu! Don leat listtus.","licence.title":"AI-gile: fitnodatlisensa","licence.description":"Geavahat go AI-gilii iežat fitnodagas? Ohcal friddja fitnodatlisensa.","licence.h1":"📜 Fitnodatlisensa","licence.lede":"Geavahat go AI-gilii barggus? Muital geat don leat ja maid dahkat. Jos dat dahká veahkkelaš, lisensa lea friddja.","licence.company":"Fitnodat","licence.website":"Neahttasiidu","licence.what":"Maid dahkat","licence.how":"Mo dat veahkeha máilmmi","licence.email":"E-poasta","licence.submit":"Ohcal","licence.thanks":"Giitu! Mii vástidit e-poastta bokte.","status.title":"AI-gilen dilli","status.h1":"AI-gilen dilli","status.quiet":"Buot jaskat","status.intro":"Doaibmágo AI-gile dál? Dát siidu dárkkista neahttasiiddu, tavlaid juogadeami, riŋgemiid ja viežžama juohke 5. minuhta.","status.up":"Doaibmá (vástidii {ms} ms:s)","status.slow":"Ii vástidan maŋimuš dárkkisteapmái, geahččala fas","status.down":"Ii doaibma: ii vástidan guovtti maŋimuš dárkkisteapmái","status.svc.web":"Neahttasiidu","status.svc.web.offers":"Dát siidu: mii AI-gile lea, ja beroštumi skovvi","status.svc.boards":"Tavlaid juogadeapmi","status.svc.boards.offers":"Almmolaš tavllat, dieđut ustibiid gaskka ja bovdejumit","status.svc.calls":"Riŋgemat","status.svc.calls.offers":"Jietna, video ja šearbmajuogadeapmi AI-giles","status.svc.download":"Viežžan","status.svc.download.offers":"Windows-sajáiduhtti ja bovdejumi liŋkkat","status.checking":"Dárkkista…","status.offline":"Dál ii leat vejolaš olahit dillebálvalusa (geahččala fas)","status.updated":"ođasmahtton {ago}","status.justNow":"juste dál","status.min":"{n}m dassá","status.hours":"{n}t dassá","status.days":"{n}b dassá","privacy.title":"AI-gile: maid mii vurket","privacy.h1":"Maid mii vurket","privacy.lede":"Oanehaččat: dušše dan maid don sáddet midjiide, ja ii guhká.","privacy.only":"Dušše dan maid don sáddet midjiide: maid čálát skovvái, nugo du e-poastta. Ii maidege eará du birra.","privacy.sealed":"Dat sealljejuvvo nu ahte min server ii sáhte dan lohkat: du neahttalohkkis ovdal go vuolgá (boares neahttalohkkis, dalle go joavdá). Dušše min iežamet tavla sáhttá dan rahpat.","privacy.server":"Dat sihkkojuvvo serveris dalán go joavdá min tavlii. Buot mii lea doppe ain 30 beaivvi maŋŋá, sihkkojuvvo goitge.","privacy.board":"Mii vurket dan min tavllas dušše dassážii go leat vástidan dutnje, ja de sihkkut dan doppe maid.","privacy.none":"Eai čuovvuleaddjit, eai cookie:t, ii analysa.","privacy.local":"Du giella ja čuovga- dahje sevdnjes ivdneválljen bissot du iežat neahttalohkkis. Dat eai goassege sáddejuvvo midjiide.","privacy.ask":"Háliidatgo dan jávkat árabut? Vástit min e-poastii ja daja dan.","live.h2":"Čuovo goas dat huksejuvvo, njuolga","live.caption":"Juohke kortta lea čiehkas: don oainnát barggu hápmi, it sániid.","live.watching.one":"njuolga: {n} čuovvu","live.watching.other":"njuolga: {n} čuovvu","live.last.now":"Maŋimus kortta lea sirdojuvvon dál","live.last.min.one":"Maŋimus kortta sirdojuvvui {n} minuhtta áigi","live.last.min.other":"Maŋimus kortta sirdojuvvui {n} minuhta áigi","live.last.hour.one":"Maŋimus kortta sirdojuvvui {n} diimmu áigi","live.last.hour.other":"Maŋimus kortta sirdojuvvui {n} diimmu áigi","live.last.day.one":"Maŋimus kortta sirdojuvvui {n} beaivvi áigi","live.last.day.other":"Maŋimus kortta sirdojuvvui {n} beaivvi áigi","live.offline":"Njuolgabeavdi vuoiŋŋasta veaháš. Bija fas čađa dalle.","live.cols":"Backlog|Dahkat|Barggus|Joavku dárkkista|Dutnje testit|Joavkku|Gárvvis","pitch.words.two":"{n} sáni","pitch.letters.two":"{n} bustávva","pitch.chars.two":"{n} mearkka","count.line.html.two":"{n} korttá tavllas dál","tl.cards.two":"{n} korttá"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robohtat.","Sáddejuvvon."]},{"n":2,"texts":["Kanban robohtaide.","Agenttat, ortnegis.","Jurddat, huksejuvvon."]},{"n":3,"texts":["Kanban robohtaide várás.","Jurddat šaddet doaimmaide.","Friddja agenttakanban."]},{"n":5,"texts":["Kanban-tavla maid agenttat jođihit dutnje.","Don čállát kortaid. Agenttat hukset.","Friddja, báikkálaš, geahččaluvvon, veaháš jatnat."]},{"n":8,"texts":["Friddja kanban-tavla mas AI-agenttat barget du ovddas juohke áiggi.","Čále jurdaga. Agenttat hukset. Don dohkket.","Agile ovtta olbmui ja ollu bohtosis robohtaide."]},{"n":13,"texts":["Kanban-tavla du iežat dihtoris, mas AI-agenttat váldet kortaid iežaset bargun ja dahket daid.","Čále jurdaga. Agenttaid joavku hukset dan. Dasto geahččaleaddji dárkkista dan ja dutnje boahtá ruoktot.","Friddja, almmá kontuid ja čuovvuleaddjiid: tavla, soames robohta ja don jođiheaddjin."]},{"n":21,"texts":["AI-gile lea kanban-tavla mii veahkeha du bargat AI-prográmmenagenttaiguin. Sii váldet kortaid iežaset bargun; don geahččalat daid ja dohkket daid.","Juohke prošeakta oažžu iežas jođiheaddji ja AI-agenttaid joavkku. Čále kommeantta ovtta kortii, ja dalle joavku álggaha bargat dan ala.","Friddja persovnnalaš bargolistu mii johtá du iežat dihtoris. Bargit leat robohtat. Dat gii dadjá juo leat don."]},{"n":34,"texts":["Don bijat jurdagiid tavlii. AI-agenttaid joavku dahká daid doaibmi funkšuvnnaid, geahččala daid ja addá daid ruoktot dutnje geahččalanlávkkiiguin maid sáhttá čuovvut. Maidege ii lohkkojuvvo gárvvisin ovdal go don iežat dadjat dan.","AI-gile lea ruovttuin dahkkojuvvon kanban-tavla maid Rich lea huksen ollu veahkkin agenttain geaid dat dál jođiha. Dat lea friddja, johtá du dihtoris, ja juogaduvvo ustibiidda, ii vuvdojuvvo.","Jurddaš dábálaš kanban-tavlla, mas leat ráiddut Backlogas Gárvvisii, muhto kortaid váldet AI-agenttat. Sii muitalit mo bargu manná, jerret go bidjet ja vuordet álo du dohkkehusa. Ja bargit eai leat olbmot."]},{"n":55,"texts":["AI-gile lea kanban-tavla gos joavku lea dahkkojuvvon AI-agenttain. Juohke prošeavttas lea jođiheaddji gii plánen barggu, ja veahkkehat geat hukset dan. Go ominaivvas lea gárvvis, AI-geahččaleaddji geahččala dan ja váldá ruvttagova, ja dasto dat boahtá du čoalkkuide. Dohkke dan, dahje čále kommeantta ja sii dahket fas.","Dat álggii ovtta olbmo vugiin doallat guovddážis ollu AI-prográmmensessuvnnaid oktanaga, ja šattai riekta tavlan. Dat johtá du mášiinnas, ii bivdde konttu, ja das eai leat čuovvuleaddjit. Dat lea friddja ustibiidda ja buohkaide geat leat miellagiddevaččat. Dat ii leat vel gárvvis, nu vuordde veaháš garra ravddaid ja muhtumin hui earálágan bohtosiid.","Dát lea duohta veršuvdna. Don ferte ain hutkat jurdagiid, ja don ferte ain dárkkistit bohtosiid. AI-gile dahká buot maid das gaskkas: doallá kortaid ortnegis, čuoččáha riekta agenta go čállát kommeantta, čájeha dárkilit mii lea rievdan, ja čohkke buot ovtta oanehis čoalkkus dutnje. Ii eambbo, ii unnit. Dat lea unna ja ráhkis bargu, mii ii leat vel gárvvis muhto lea juo ávkkálaš."]},{"n":89,"texts":["AI-gile lea friddja kanban-tavla maid don johtát iežat dihtoris. Olbmuid sadjái juohke prošeavttas lea AI-agenttaid joavku: jođiheaddji gii dahká du jurdagiin kortaid ja plána, ja veahkkehat geat váldet kortaid deatalašvuođa mielde. Go juoga lea huksejuvvon, AI-geahččaleaddji čuovvu geahččalanlávkkiid ja čájeha dutnje maid oaidnigođii. Dasto dat vuordá oktan čoalkkus man namma lea Dutnje. Don dohkket dan, dahje čálát kommeantta ja joavku geahččala fas. Buot dat dáhpáhuvvá du iežat dihtoris, ja dieđut eai guođe dan. Maidege ii goassige joavdda Gárvvisii almmá dutnje.","Moadde ášši maid it vuorddáše. Ijavuohta doallá Dahkat-ráiddu devdojuvvon go don oađát, válljemin kortaid maidda ii dárbbaš du vástádusa. Token-lohkki čájeha man ollu agenttat leat geavahan otne ja dán vahkus, ja Ii-token-vuohki dadjá sidjiide heaitit lonuheamis. Don sáhtát čálihit ustibiiguin, ja priváhta čállosat leat gaskkohagas čihkkojuvvon. Tavla hupmá sullii 120 giela, earret eará hollánddagiela, flámagiela, mearrarievvárgiela ja klingona. Ii oktage dáin máksa ruhta, ja ii oktage geahččal dutnje vuovdit dan. Buot dat lea dahkkojuvvon vai don sáhtát oađđit buorebut.","AI-gile lea smávva persovnnalaš prošeakta, ii fitnodat. Rich háliidii dovdat máŋga AI-prográmmenprošeavtta almmá rahpamin juohke appa, ja son ja agenttat hukse dan várás tavla, ja geavahedje dan tavlla iežas loahpa huksema várás. Dat lea gidda pre-alfas, mii oaivvilda ahte dat doaibmá, eanaš, moadde ustibii várás. Eai leat hinddasiidu, eai ođđasat eaige šaddanplána. Jos dat orru ávkkálažžan, sáhtát bivdit geahččalit go rahpasa veaháš eanet. Dat lea ain dáhpáhuvvame, ja jearaldagat leat buorit."]},{"n":144,"texts":["AI-gile lea kanban-tavla ovtta olbmui ja ollu AI-agentii. Dat johtá du iežat dihtoris ja lea áibbas friddja. Eai kontut, eai čuovvuleaddjit. Don lasihat prošeavttaid, ja juohke prošeakta oažžu jođiheaddji ja smávva joavkku. Don hupmat jođiheaddjiin, veaháš Discord-lágán, ja čilget jurdaga; jođiheaddji dahká das kortaid ja plána, ja dasto vuordá go deaddilat Go. Joavku bargá kortaid čađa deatalašvuođa mielde, geavahemiin álkes gohččunlinjá mii lea dahkkojuvvon giellamodeallaide. Ovdal go maidege máhccá dutnje, AI-geahččaleaddji čuovvu lávkkiid appa kopiias ja lasiha ruvttagova. Gárvvis bargu boahtá du čoalkkuide rievdaduvvon fiillaiguin ja erohusain. Don dohkket dan, dahje guođát kommeantta ja joavku čuoččáha ja geahččala fas. Juohke dohkkehus lea du, ja juohke ruoktotaddin lea dutnje čielggas ja álkes. Dušše don sáhtát sirdit kortta Gárvvisii.","Beaivi AI-gilin, sulaid nu. Eahkedis don guođát moadde kommeantta: dát boallu lea boastut sajis, dat listu galggašii leat ortnegis, sáhttá go leat čáhppes vuohki. Don manat oađđit. Agenttat lohket kommeanttaid, dahket rievdadusaid, geahččalit daid ja addet ruoktot. Jos Dahkat gerddiha, ijavuohta deavdá dan backlogas kortaiguin maidda ii dárbbaš du vástádusa. Iđđes lea okta oanehis čoalku: guokte gažaldaga ja moadde juoga maid geahččalit, juohkehaččas lávkkit maid váiban olmmoš sáhttá čuovvut ja ruvttagovva mii čájeha ahte doaibmá. Don deaddilat čađa, dohkket buriid ja sáddet ruoktot eará. Token-lohkki čájeha man ollu dat geavahii, ja Ii-token-vuohki lea unna vahkuid várás. Go dus lea áigi, don sáhtát čállit eanet jurdagiid, ja joavku váldá daid maŋŋel. Dasto don borat iđitboradeami, mas agenttat eai sáhte vel veahkehit.","Vuos, mii AI-gile ii leat. Dat ii leat startup, ii vuovdojuvvo, ja ii oktage čohkke du dieđuid. Dat lea friddja tavla mii johtá du dihtoris, almmá kontuid, čuovvuleaddjiid ja cookie:id. Mii dat lea: okta čorgat báikki gos oainnát buot AI-prográmmenprošeavttaid oktanaga, agenttajoavkkuin mat dahket kortaid ja don mearridat. Dat čohkke seammalágan kortaid, divvu seaguhuvvan namaid ja čuovvu man geahpas koda orru. Dat hupmá sullii 120 giela, hollánddas ja flámmas mearrarievvárgillii ja klingonii. Ustibat sáhttet čállit goabbat guoibmásis, priváhta ja gaskkohagas čihkkojuvvon. Dan leat hukse Rich ja ollu bohtosis agenttat, eanaš geavahemiin dan iežas. Dat lea gidda pre-alfas, nu dat lea báikkiid garra. Jos dat gullo hávskin, bivdde čábbát ja soaitá beassat árrat sisa. Ja dat lea juo veaháš suohtas."]}],"quips":{"1":"Okta sátni. Duostil. Vejolaččat menddo duostil.","3":"Golbma sáni. Juo eanet duohta go eanaš buvttahusa siiddut.","8":"Gávcci sáni. Ain oanehit go stand-up.","21":"Guhkkodagat leat muhtumin story points. Dieđusge.","55":"Vihtanuppelohkái-vihtta sáni. Guokte korttá šattai gárvvisin dan botta go lohkat.","144":"Dát lea guhkes. 233 ii gávdno. Agenttat leat vuolgán oađđit."}},"timeline":{"first-idea.name":"Vuosttaš jurdda","first-idea.line":"Aiddo vuosttaš sártnut, ovdal go ledje koda.","first-board.name":"Vuosttaš tavla","first-board.line":"Tavla mii čuovvu iežas huksema: kortta, ráiddut, geassit ja luoitit, prošeavttat.","team-roles.name":"Joavku ja rollat","team-roles.line":"Agenttaprofiillat, joavkomállet, sajit ja geasa mii gullá.","install.name":"Sajáiduhttin ja versjonat","install.line":"Zip maid ustit sáhttá sajáiduhttit, iehčasis ođasmahttin, kanálat ja máhccan.","usage-saver.name":"Geavaheami sihkkarastin","usage-saver.line":"Mihtit man divrras bargut leat, doala koda geahpesin, suodjal iežat ráji.","friends.name":"Ustibat ja juogadeapmi","friends.line":"Priváhta čállosat, ruvvejuvvon reléa, bovdehusat, rollat ja juogaduvvon prošeavttat.","languages.name":"Gielat","languages.line":"Juohke čájáhusteaksta giellafiillas, hollánddagiella ja flámagiella vuos.","ai-tester.name":"AI-geahččaleaddji","ai-tester.line":"Geahččaleaddji dárkkista juohke addima ovdalgo ja čájeha maid oaidnigođii.","website.name":"Neahttasiidu","website.line":"aigile.lol, teaser ja dát áigeráidu.","streaming.name":"Chat ja streama","streaming.line":"Discord, Twitch, OBS, streamer-vuohki, GIF:at ja emoji:t.","no-ai.name":"Ilá AI-veršuvdna","no-ai.line":"Tavla sidjiide geat koda ilá AI:a, ja almmolaš tavllat.","night-watch.name":"Ijavuohta","night-watch.line":"Vuohttu ja Scrum Master doalahit joavkkuid barggus go don oađát.","p-more.name":"Buot eará","p-more.line":"Smávit jurddat mat vuordet iežaset vuoru.","p-android.name":"Telefovdna ja Android","p-android.line":"Olat tavlii telefovnnas, ja ovdal eaiggátlaš Android-appa.","p-release.name":"Alfa ja dan maŋŋá","p-release.line":"Gidda alfa, njuolgga neahttasiidu, de beta.","p-languages.name":"Eanet gielat","p-languages.line":"Eanet go čuođi giela, ja sisabuktinvuohki sidjiide geat oahppet.","p-engines.name":"Eanet AI-mohtorat","p-engines.line":"Vállje Claude, Codex dahje Gemini juohke agentii.","p-pro.name":"Proffalaš geavahus","p-pro.line":"Riskamearkkat, ovttastahttinlásit, váttisvuođakortta ja suodjalusat.","p-self.name":"Fuolahit duinna","p-self.line":"Váibmu-vuohki, iežas fuola muittuhusat ja 4:20.","p-servers.name":"Serverat ja šaddan","p-servers.line":"Máilmmeviidosaš server-heivehusat, rollat ja plánen šaddama várás.","p-livestream.name":"Streama lassin","p-livestream.line":"Twitch-chat, iežat emoji:t ja almmolaš njuolgga oaidnu."},"words":{"button":"📖 Fágasánit","h":"📖 Sánit čilgejuvvon","intro":"Sánit maid deaivvat AI-gile:s, álkes gillii: huksen, sihkkarit rievdadit, doalahit doaimmas sidjiide geat geavahit dan, ja bargat joavkun AI:in.","search":"Oza sáni…","none":"Ii oktage sátni heive.","close":"Gidde","count":{"one":"{count} sátni","other":"{count} sáni"},"groups":[{"id":"build","name":"🛠️ Huksen"},{"id":"change","name":"🔀 Sihkkarit rievdadit"},{"id":"run","name":"🛎️ Bálvalusa jođiheapmi"},{"id":"team","name":"🤝 Bargat joavkun (ja AI:in)"}],"list":[{"id":"repo","g":"build","word":"Repo","text":"Prošeavtta máhpa mas lea koda ja dievaslaš commits-historjá, dábálaččat maiddái vurkejuvvon GitHub:s.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"Sierra bargolinjá koda siste, nu ahte rievdadusat sáhttet dahkkot almmá váldoveršuvnna lonohallamis.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"Vurkejuvvon govva koda dilis, oanehis muitalusain das mii rievddai. Don sáhtát álo mannat ruovttoluotta ovtta.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"Sáddet vurkejuvvon govaid (commits) dán dihtoris GitHub:ii, nu ahte dat leat várrejuvvon ja juogaduvvon."},{"id":"merge","g":"build","word":"Merge","text":"Ovttastahttit branch rievdadusaid fas váldoveršuvdnii."},{"id":"pr","g":"build","word":"Pull request","text":"Bivdit ahte branch rievdadusat dárkkistuvvojit ja ovttastahttojuvvojit váldoveršuvdnii.","also":["PR"]},{"id":"refactor","g":"build","word":"Refactor","text":"Ordnet koda almmá rievdadeamis maid dat dahká: unnit fiillat, čielgasat nammat, unnit geardduheapmi."},{"id":"bug","g":"build","word":"Bug","text":"Juoga mii ii doaimma nu go galggai.","also":["bugs"]},{"id":"test","g":"build","word":"Test","text":"Geahččalit gárvvis bargojaddasa dárkkistit ahte dat dahká maid jerrojuvvui, ovdalgo dohkket.","also":["tests"],"noTip":1},{"id":"qa","g":"build","word":"QA","text":"Oanádus sániin quality assurance, kvalitehtasihkkarastin: automáhtalaš dárkkisteamit mat jođihuvvojit ovdal go mihkkege manná live. Go QA lea ruoksat, juoga lea boatkanan, ja dat ii sáhte manat live ovdal go dat lea divvojuvvon.","also":["kvalitehtadárkkisteapmi","quality assurance"]},{"id":"deploy","g":"change","word":"Deploy","text":"Bidjat ođđa veršuvnna eallima, ee. servera alde gos olbmot geavahit dan."},{"id":"release","g":"change","word":"Ođasmahttin","text":"Gárvvis bargu nammaduvvon čoahkkái, mii manná live oktanaga, oanehis čállosiiguin das mii rievddai. 🚀 Ođasmahttimat čállá čállosiid gárvvistuvvon korttain.","also":["ođasmahttimat","release"]},{"id":"rollback","g":"change","word":"Rollback","text":"Máhccat maŋimuš veršuvdnii mii doaimmai, go ođđa veršuvdna dagaha váttisvuođaid. AI-gile:s dat dahká dárkkistanlisttu máhcahanlávkkiin mat leat čállojuvvon juohke rievdadussii.","also":["máhcaheapmi","máhccat ovddit veršuvdnii","roll back"]},{"id":"live","g":"change","word":"Live","text":"Duohta veršuvdna maid olbmot geavahit, iige máŋga maid geahččalit. Prográmmenddit gohčodit dan maiddái production.","also":["buvttadeapmi","production"],"noTip":1},{"id":"change","g":"change","word":"Rievdadus","text":"Plánejuvvon rievdadus juoga masa olbmot luhttet, vuos čállojuvvon: mii, manne, riska, goas ja mo dan máhcahit. Álggat dakkára 🔀 Bivdde rievdadusa boaluin.","also":["rievdadusat","rievdadusbivdda","change request"],"noTip":1},{"id":"risk","g":"change","word":"Riska","text":"Juoga mii sáhttá mannat boastut, árvvoštallojuvvon dan mielde man jáhkehahtti ja man heajos dat livččii. ⚠️ Riskkat doallá daid ovtta listtus, alimus čuoggát vuosttažin, juohkehaččas beaivi goas fas geahččat.","also":["riskkat","riskaregisttar"]},{"id":"chgwin","g":"change","word":"Rievdadusláse","text":"Áiggit goas rievdadusat sáhttet manat live, nugo jaskes disdatiehke. Láse olggobealde rievdaduskortta ii sáhte gárvvistit, earret go lea heahtediliin.","also":["rievdadusláset","change window"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"Jođánis jienasteapmi juste ovdal go rievdadus manná live: juohkehaš gii galgá dohkkehit dadjá Go dahje No go. Dat manná ovddos dušše go buohkat leat ovttaoaivilis.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Dohkkeheapmi","text":"Vuordit juo ovdal go bargu álgá. Kortta maid ustit lea bidjan, dahje rievdadus, vuordá ✅ Dohkkehusain dassážii go don dohkkehat dahje hilggut dan.","also":["dohkkehusat","dohkkehus"]},{"id":"quiettime","g":"change","word":"Jaskes áigi","text":"Áigodat, nugo stream, demo dahje idja, goas ii mihkkege mana live. Joavkkut barget ja geahččalit ain, muhto live-manna vuordá dassážii go dat nohká. Earáin dat gohčoduvvo rievdadusjiekŋun.","also":["jaskes áiggit","rievdadusjiekŋun","change freeze"]},{"id":"service","g":"run","word":"Bálvalus","text":"Juoga maid don leat huksen ja masa olbmot luhttet, nugo neahttasiidu dahje app, mii fuolahuvvo vai doaibmá ain. Merke “Dát prošeakta lea bálvalus” ja čále maid dat fállá, geat geavahit dan ja gii lea gohččumis.","also":["bálvalusat"]},{"id":"uptime","g":"run","word":"Doaibmaáigedárkkisteapmi","text":"Automáhtalaš dárkkisteapmi juohke moatti minuhta, ahte du bálvalus ain vástida. Jus dat boatkana máŋgii maŋŋálagaid, AI-gile rahpá dáhpáhuskortta ieš.","also":["uptime","doaibmaáigi","uptime check"]},{"id":"statuspage","g":"run","word":"Dilálašsiidu","text":"Almmolaš siidu mii čájeha doaibmágo bálvalus (ruoná, oránša dahje ruoksat) ođđaseamos dieđuin, vai sii geat geavahit dan sáhttet ieža geahččat iige dárbbaš jearrat.","also":["dilálašsiiddut","status page"]},{"id":"incident","g":"run","word":"Dáhpáhus","text":"Juoga mii lea billašuvvan dálle sidjiide geat geavahit dan, nugo neahttasiidu ii doaimma. 🔥 Dáhpáhuskorta njuiká jorgga ovddabeallái: vuosttažin dat galgá fas doaibmat.","also":["dáhpáhusat","incident"]},{"id":"major","g":"run","word":"Stuorra dáhpáhus","text":"Stuorra dáhpáhus: ollu olbmot čuhcet, dahje ruhta dahje dieđut leat váras. Okta boallu bidjá buot joavkkuid dasa (swarm), boktá su gii lea gohččumis ja bivdá stáhtusođasmahttima juohke 30 minuhta.","also":["stuorra dáhpáhusat","stuorra váttisvuohta","major incident"]},{"id":"oncall","g":"run","word":"Gohččumis","text":"Leat dat gii vástida go juoga billašuvvá, ijage. Juohke bálvalusas lea joavkolahttu gohččumis, gii boktojuvvo vuosttažin bálvalusa dáhpáhusaid dihtii.","also":["gohččunvákta","on call","on-call"]},{"id":"replyby","g":"run","word":"Vástádusáigi","text":"Man guhká korta oažžu vuordit vuosttaš vástádusa, ovdamearkka dihtii diimmu dáhpáhussii. Dan maŋŋá dat oažžu rukses diimmu, vai ii mihkkege jávohaga vajálduva. Gohčoduvvo maiddái vástidanmihttun.","also":["vástádusáiggit","vástidanmihttu","response target"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"Oanehis geahčastat maŋás dáhpáhusa maŋŋá: mii dáhpáhuvai, mii veahkehii ja maid rievdadit, ii ge oktage cuiggoduvvo. Dáhpáhusa ii sáhte giddet dan haga.","also":["post-mortems","postmortem","dáhpáhusa maŋŋágeahčadeapmi"]},{"id":"problem","g":"run","word":"Váttisvuohta","text":"Čiehkkon sivva ovtta dahje eanet dáhpáhusa duohken. 🧩 Váttisvuođakorta čohkke dáhpáhusaid mat máhcašit, vai sivva gávdnojuvvo ja divvojuvvo áibbas.","also":["váttisvuođat","problem"],"noTip":1},{"id":"rootcause","g":"run","word":"Vuođđosivva","text":"Duohta sivva manne juoga billašuvai, ii dušše dat maid oidnet mannamin boastut. Divvo vuođđosiva, de dáhpáhus ii šat máhca.","also":["vuođđosivat","root cause"]},{"id":"workaround","g":"run","word":"Gaskaboddosaš čoavddus","text":"Vuohki doalahit áššiid doaimmas dassážii go duohta divvun lea gárvvis, nugo álggahit juoga ođđasit go dat heaŋgá. Dat čállojuvvo váttisvuođakortii, vai ii oktage dárbbaš dan fas gávdnat.","also":["gaskaboddosaš čovdosat","workaround"]},{"id":"knownerror","g":"run","word":"Dovdojuvvon meattáhus","text":"Váttisvuohta man sivva lea áddejuvvon ja mas lea gaskaboddosaš čoavddus, muhto mii ii leat vel divvojuvvon. 🧩 Dovdojuvvon meattáhusat listu daid, vai buohkat geavahit gaskaboddosaš čovdosa iige ohca ođđasit.","also":["dovdojuvvon meattáhusat","known error"]},{"id":"runbook","g":"run","word":"Runbook","text":"Lávki lávkki mielde rávvagat dovdojuvvon lágan váttisvuođa divvumii, vai dat dahkko seamma láhkai, jođánit, juohke háve. Stuorra dáhpáhusa maŋŋá joavku sáhttá evttohit dakkára maid don dohkkehat.","also":["runbookat","bargonjuolggadus"]},{"id":"backup","g":"run","word":"Sihkkarastin","text":"Vurkejuvvon máŋga du dieđuin ovdal, man ala sáhtát máhccat jus juoga láhppo dahje billašuvvá. AI-gile dahká juohke beaivvi sihkkarastima du távvaliin.","also":["sihkkarastimat","backup","sihkkarastinmáŋga"]},{"id":"restore","g":"run","word":"Máhcaheapmi","text":"Bidjat dieđuid ruovttoluotta sihkkarastimis. Sihkkarastin lea duođas árvvolaš dušše go dieđát ahte dan sáhttá máhcahit, nu ahte ávkkálaš geahččalit dan muhtumin.","also":["máhcat","máhcahuvvon","restore"]},{"id":"backlog","g":"team","word":"Backlog","text":"Jurdagat ja bargu mat eai leat plánejuvvon vel. Dasa ii dahkko maidege ovdalgo dat sirdojuvvo Dahkat:ii."},{"id":"sprint","g":"team","word":"Sprint","text":"Oanehis bargojahki (dávjá vahkku dahje guokte) sohppojuvvon korttaiguin.","also":["sprints"]},{"id":"standup","g":"team","word":"Stand-up","text":"Jođihis dárkkisteapmi: maid juohke joavkolahttu dagai, maid son dahká boahtte, ja mii bissu su.","also":["standup","stand-ups"]},{"id":"kanban","g":"team","word":"Kanban","text":"Tavla čuoggáiguin (Dahkat, Barggus, Gárvvis) gos kortta sirdojuvvojit gurutguovllus olgešguvlui go bargu manná ovddos."},{"id":"wip","g":"team","word":"WIP-ráddjehus","text":"Work in progress: eanemus kortta mat čuoggás sáhttet leat, nu ahte joavku lágida áššiid gárvvisin ovdalgo álggaha eanet.","also":["WIP"]},{"id":"dod","g":"team","word":"Gárvvistuvvon meroštus","text":"Joavkku oanehis dárkkistanlistu das mii “gárvvis” mearkkaša, nugo geahččaluvvon ja čilgejuvvon, ovdal go korta addojuvvo dutnje. Dan guoibmi, Gárvvis meroštus, dadjá goas korta lea doarvái čielggas álggahit.","also":["Definition of Done","DoD","Gárvvis meroštus","Definition of Ready"]},{"id":"testpile","g":"team","word":"Test-bunka","text":"Gárvvistuvvon korttat mat vurdet ahte don geahččalat daid, okta nuppi maŋis. Dohkket ovtta dahje sádde dan ruovttoluotta čállosiin, de boahtá čuovvovaš.","also":["test pile","test-bunkkas"]},{"id":"retro","g":"team","word":"Retro","text":"Geahčastat maŋás dasa mo joavku bargá, vai šiehttat ovtta ášši maid buorebut dahkat. AI-gile:s retro evttoha rievdadusa joavkku bargovugiide, ja don dadjat Mana dahje Ii vel.","also":["ruovttoluotta geahčadeapmi","retrospektiiva"]},{"id":"peerreview","g":"team","word":"Peer review","text":"Nubbi čalbmeguoktá: nubbi AI dárkkista juohke kortta barggu ovdal go dat joavdá dutnje, nu ahte unnit meattáhusat mannet čađa.","also":["code review","ustitgeahčadeapmi"]},{"id":"swarm","g":"team","word":"Swarm","text":"Buohkat mielde: juohke joavku guođđá eará barggu ja veahkeha ovtta hoahppu prošeavttain dassážii go dat lea čovdojuvvon. Eará prošeavttat vurdet dan botta.","also":["rávvi","swarming"]},{"id":"scrummaster","g":"team","word":"Scrum Master","text":"Son gii doallá barggu johtui: fuomáša heaŋgájeaddji korttaid, movttiidahttá joavkkuid ja muittuha du dan birra mii vuordá. AI-gile:s Lead Scrum Master dahká dan buot prošeavttain.","also":["Lead Scrum Master"]},{"id":"agent","g":"team","word":"Agent","text":"AI mii bargá iežas ovtta bargguin: lohká koda, dahká rievdadusaid, jođiha dárkkisteamiid, ja raporttá.","also":["agents"]},{"id":"token","g":"team","word":"Token","text":"Ovttadat maid AI-geavahus lohkkojuvvo: measta moadde bustávva teavstta lohkkojuvvon dahje čállojuvvon. Unnit tokens, eanet báhcá du plánas.","also":["tokens"]},{"id":"hook","g":"team","word":"Hook","text":"Uhcci gohččun mii johtá iehčanis mearrejuvvon hetkiin, ee. go AI-sešuvdna álgá, nu ahte joavku gullá du kommeanttaid.","also":["hooks"]}]}};
